import {solution,pageLayout,TIERS} from './worksheet-model.js?v=18';
import {diagramImage} from './worksheet-diagram.js?v=18';
let ready;
function base64(buffer){let s='';for(const n of new Uint8Array(buffer))s+=String.fromCharCode(n);return btoa(s);}
async function dependencies(){return ready??= (async()=>{if(!globalThis.jspdf)await new Promise((resolve,reject)=>{const s=document.createElement('script');s.src=new URL('./vendor/jspdf.umd.min.js',import.meta.url);s.onload=resolve;s.onerror=()=>reject(Error('Unable to load PDF tools. Please reload.'));document.head.append(s)});const fonts=await Promise.all(['DejaVuSans.ttf','DejaVuSans-Bold.ttf'].map(async name=>{const r=await fetch(new URL('./vendor/'+name,import.meta.url));if(!r.ok)throw Error('Unable to load print fonts.');return base64(await r.arrayBuffer())}));const font=new FontFace('WorksheetFont',`url(${new URL('./vendor/DejaVuSans.ttf',import.meta.url)})`);document.fonts.add(await font.load());return fonts;})();}
export async function createPDFs(model){const fonts=await dependencies(),bm=model.language==='bm',tr=(en,ms)=>bm?ms:en,topic=model.mode==='straight'?tr('Angles on a Straight Line','Sudut pada Garis Lurus'):tr('Angles Around a Point','Sudut di Sekeliling Titik');const pdf=new jspdf.jsPDF({unit:'mm',format:'a4',compress:true,putOnlyUsedFonts:true});fonts.forEach((f,i)=>{const name=i?'DejaVuSans-Bold.ttf':'DejaVuSans.ttf';pdf.addFileToVFS(name,f);pdf.addFont(name,'Worksheet',i?'bold':'normal')});
 function text(value,x,y,size=10,bold=false,width=182){pdf.setFont('Worksheet',bold?'bold':'normal');pdf.setFontSize(size);pdf.setTextColor(25);const lines=pdf.splitTextToSize(String(value),width);pdf.text(lines,x,y,{lineHeightFactor:1.2});return y+lines.length*size*.3528*1.2;}
 function footer(index,answers=false){pdf.setDrawColor(190);pdf.line(14,283,196,283);text(`${tr('Seed','Benih')}: ${model.seed}`,14,288,8,false,148);text(`${answers?tr('Answers','Jawapan'):tr('Worksheet','Latihan')} ${index}`,163,288,8,false,33);}
 function heading(page,answers=false){let y=model.title?14:18;if(model.title)y=text(model.title,14,y,12,true)+2;y=text(topic,14,y,14,true)+2;text(`${tr('Tier','Tahap')} ${page.tier} — ${TIERS[page.tier-1][bm?1:0]}${answers?' • '+tr('Answers','Jawapan'):''}`,14,y,10,true);if(!answers){text(tr('Name: __________________   Class: __________   Date: __________','Nama: __________________   Kelas: __________   Tarikh: __________'),14,42,9);text(tr('Find the unknown angle. Show your working. Diagrams are not to scale.','Cari sudut yang tidak diketahui. Tunjukkan cara kerja. Rajah tidak mengikut skala.'),14,48,9);} }
 function working(q,x,y,width,size=10){const s=solution(q,model.language);y=text(s.rule,x,y,size,false,width)+2;for(const step of s.steps)y=text(step,x,y,size,step===s.steps.at(-1),width)+1;y=text(s.check,x,y,8.5,false,width);return y;}
 for(let i=0;i<model.pages.length;i++){if(i)pdf.addPage();const page=model.pages[i];heading(page);pdf.setDrawColor(180);pdf.setFillColor(248);pdf.roundedRect(14,53,182,80,2,2,'FD');text(tr('Worked Example','Contoh Penyelesaian'),18,60,11,true);text(`${tr('Find','Cari')} ${page.example.symbol}.`,18,66,9);pdf.addImage(diagramImage(page.example,74,59),'PNG',17,69,74,59);const end=working(page.example,96,67,95,9.5);if(end>130)throw Error('The worked example exceeds its page space. Try another seed.');const blocks=pageLayout(page.tier,page.questions.length);for(let j=0;j<page.questions.length;j++){const {number,question:q}=page.questions[j],b=blocks[j];text(`${number}. ${tr('Find','Cari')} ${q.symbol}.`,b.x,b.y+4,10,true);const wide=b.width>100,dh=wide?Math.min(51,b.height-10):41,dw=wide?79:b.width;pdf.addImage(diagramImage(q,dw,dh),'PNG',b.x,b.y+7,dw,dh);pdf.setDrawColor(190);const start=wide?b.x+87:b.x,top=wide?b.y+17:b.y+49;for(let y=top;y<b.y+b.height-3;y+=6)pdf.line(start,y,b.x+b.width,y);}footer(i+1);await new Promise(r=>setTimeout(r,0));}
 const student=pdf.output('arraybuffer');for(let i=0;i<model.pages.length;i++){pdf.addPage();const page=model.pages[i];heading(page,true);const height=230/page.questions.length;for(let j=0;j<page.questions.length;j++){const item=page.questions[j],top=45+j*height;text(`${item.number}. ${tr('Find','Cari')} ${item.question.symbol}.`,14,top,11,true);const end=working(item.question,20,top+7,172,10);if(end>top+height-3)throw Error('The answer section exceeds its space. Choose fewer questions.');}footer(i+1,true);}return{student,teacher:pdf.output('arraybuffer')};}
export async function createPrintDocument(){const fonts=await dependencies();const pdf=new jspdf.jsPDF({unit:'mm',format:'a4',compress:true,putOnlyUsedFonts:true});fonts.forEach((f,i)=>{const name=i?'DejaVuSans-Bold.ttf':'DejaVuSans.ttf';pdf.addFileToVFS(name,f);pdf.addFont(name,'Worksheet',i?'bold':'normal')});pdf.setFont('Worksheet');return pdf;}
